WYK_WarTools.CommandLine = function(text)	if not text or text == "" or text == "help" then		d(WYK_WarTools.AddonName().." accepted commands:")		d(WYK_WarTools.Prefix.Default.." /wt  << shows help")		d(WYK_WarTools.Prefix.Default.." /wt show << shows the hidden window")		d(WYK_WarTools.Prefix.Default.." /wt hide << shows the displayed window")		d(WYK_WarTools.Prefix.Default.." /warcommand << toggles command, if group lead")		return	end		if string.find(text, "show") then		local t = text:gsub("show ","")		WYK_WarTools.UserInterface.StrategyFrame.Show()	end		if string.find(text, "hide") then		local t = text:gsub("hide ","")		WYK_WarTools.UserInterface.StrategyFrame.Hide(false)	endend